// A scoring round starts between locks: no unresolved complete row.
// Four newly locked cells can then complete at most four rows.
for (int row=0; row<study_grid::Grid::kRows; ++row)
    if (study_lines::row_full(board,row)) return std::nullopt;

// Points for 0..4 rows at a 1..20 level, or nullopt when out of range.
inline std::optional<std::uint64_t> normal_points(int rows, unsigned level) noexcept {
    if (rows < 0 || rows > 4 || level < 1 || level > 20) {
        return std::nullopt;
    }
    constexpr std::uint64_t table[5] = {0u, 100u, 300u, 600u, 1000u};
    return table[rows] * static_cast<std::uint64_t>(level);
}

struct Totals {
    std::uint64_t points = 0;
    std::uint64_t lines = 0;
};

// Level grows every 10 cleared lines and is capped at 20.
constexpr unsigned level(const Totals& totals) noexcept {
    return totals.lines >= 190u ? 20u : 1u + static_cast<unsigned>(totals.lines / 10u);
}

// Award a clear using the level before the clear; input is left untouched.
inline std::optional<Totals> award(const Totals& before, int rows) noexcept {
    const auto points = normal_points(rows, level(before));
    if (!points) return std::nullopt;
    Totals after = before;
    after.points = saturating_add(before.points, *points);
    after.lines = saturating_add(before.lines, static_cast<std::uint64_t>(rows));
    return after;
}

// Add without wrapping: clamp to UINT64_MAX on overflow.
constexpr std::uint64_t saturating_add(std::uint64_t a, std::uint64_t b) noexcept {
    constexpr auto maximum = std::numeric_limits<std::uint64_t>::max();
    return b > maximum - a ? maximum : a + b;
}

const auto scored = study_score::award(candidate.totals_,candidate.last_cleared_);
if (!scored) return Step::invalid;
const auto old_level = candidate.level();
candidate.last_awarded_ = scored->points - candidate.totals_.points;
candidate.totals_ = *scored;
if (candidate.level() != old_level) {
    const auto interval = study_score::gravity_interval(candidate.level());
    if (!interval) return Step::invalid;
    candidate.gravity_.interval = *interval;
}

// Simulation ticks per automatic drop, from 30 at level 1 to 3 at level 20.
inline std::optional<int> gravity_interval(unsigned level) noexcept {
    if (level < 1 || level > 20) {
        return std::nullopt;
    }
    return 30 - static_cast<int>(level - 1) * 27 / 19;
}

// Emit the geometry of a value; 0 still renders as a single digit.
inline Mesh make_mesh(std::uint64_t value) noexcept {
    std::array<unsigned, 20> digits{};
    std::size_t used = 0;
    do {
        digits[used++] = static_cast<unsigned>(value % 10u);
        value /= 10u;
    } while (value != 0);

    Mesh mesh;
    for (std::size_t i = 0; i < used; ++i) {
        const unsigned digit = digits[used - 1 - i];
        const unsigned mask = kDigitMask[digit];
        const float x = 8.0f + 8.0f * static_cast<float>(i);
        const float y = 4.0f;
        for (unsigned seg = 0; seg < 7; ++seg) {
            if ((mask & (1u << seg)) == 0) {
                continue;
            }
            const int* r = kSegments[seg];
            const auto quad = study_board::quad_vertices({
                x + static_cast<float>(r[0]), y + static_cast<float>(r[1]),
                x + static_cast<float>(r[2]), y + static_cast<float>(r[3]),
            });
            for (const Vertex2& v : quad) {
                mesh.vertices[mesh.count++] = v;
            }
        }
    }
    return mesh;
}
